        var strings = $scope.strings = stringSvc.getStrings(['Absence.Label.Text.NextSteps', 'Status', 'Remove', 'Cancel', 'AbsenceForm.Button.RemoveSub', 'Absence.Button.Text.AssignSub', 'Absecne.Button.Text.ReassignSub', 'Absence.Button.Text.Approve', 'Absence.Button.Text.Deny', 'Absence.Button.Text.DenyPart', 'Feedback', 'LeaveFeedbackAboutSubstitute', 'ViewFeedbackAboutSubstitute', 'LeaveFeedbackFromSubstitute', 'ViewFeedbackFromSubstitute', 'Process.text.UpdatingRecord', 'Absence.Link.Text.CreateAnotherAbsenceForThisEmployee', 'Absence.Link.Text.CreateAnotherVacancy']);

