        d.dateRange = d.startDate === d.endDate ? parseDateFilter(d.startDate, 'M/d/yyyy') : parseDateFilter(d.startDate, 'M/d/yyyy') + ' - ' + parseDateFilter(d.endDate, 'M/d/yyyy');
